<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Falling Sand Sandbox</title>
<style>
  html,body{height:100%;margin:0;background:#0b0b0f;color:#e8e8e8;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
  body{display:flex;flex-direction:column;align-items:center;gap:12px;padding:20px}
  #controls{display:flex;gap:8px;flex-wrap:wrap}
  button{background:#1e1e24;color:#e8e8e8;border:1px solid #3a3a44;padding:6px 12px;border-radius:8px;cursor:pointer;font-weight:600}
  button:hover{background:#2a2a34}
  button.active{background:#0a84ff;border-color:#0a84ff}
  canvas{border:1px solid #333;background:#000;image-rendering:pixelated;box-shadow:0 0 0 1px #222}
</style>
</head>
<body>
<div id="controls">
  <button id="mat-sand" class="active">Sand</button>
  <button id="mat-water">Water</button>
  <button id="mat-wall">Wall</button>
  <button id="mat-acid">Acid</button>
  <button id="mat-empty">Eraser</button>
  <button id="clear">Clear</button>
</div>
<canvas id="sand" width="800" height="800"></canvas>
<script>
const W = 200, H = 200, CELL = 4;
const EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
const COLORS=[ '#000000','#EDC9AF','#4A90E2','#777777','#8A2BE2' ];
const NAME = ['empty','sand','water','wall','acid'];
const CODE = {empty:0,sand:1,water:2,wall:3,acid:4};

const canvas = document.getElementById('sand');
const ctx = canvas.getContext('2d');
const grid = new Uint8Array(W*H);
let simStep = 0;
let currentMat = SAND;

function idx(x,y){ return y*W + x; }

function step(){
  simStep++;
  const orig = grid.slice();
  // movement bottom-up
  for(let y=H-2; y>=0; y--){
    for(let x=0; x<W; x++){
      const i = idx(x,y);
      if(grid[i] !== orig[i]) continue;
      const cell = orig[i];
      if(cell===EMPTY || cell===WALL) continue;
      if(cell===SAND){
        const ny = y+1;
        const di = idx(x,ny);
        if(grid[di]===EMPTY){
          grid[di]=SAND; grid[i]=EMPTY; continue;
        }
        const belowOrig = orig[di];
        if((belowOrig===WATER || belowOrig===ACID) && grid[di]===belowOrig){
          grid[di]=SAND; grid[i]=belowOrig; continue;
        }
        const dirs = [(x+y+simStep)&1 ? -1 : 1, (x+y+simStep)&1 ? 1 : -1];
        for(const dx of dirs){
          const nx = x+dx;
          if(nx<0||nx>=W) continue;
          const si = idx(nx,ny);
          if(grid[si]===EMPTY){
            grid[si]=SAND; grid[i]=EMPTY; break;
          }
        }
      }else if(cell===WATER || cell===ACID){
        const ny = y+1;
        const di = idx(x,ny);
        if(grid[di]===EMPTY){
          grid[di]=cell; grid[i]=EMPTY; continue;
        }
        const dirs = [(x+y+simStep)&1 ? -1 : 1, (x+y+simStep)&1 ? 1 : -1];
        for(const dx of dirs){
          const nx = x+dx;
          if(nx<0||nx>=W) continue;
          const si = idx(nx,y);
          if(grid[si]===EMPTY){
            grid[si]=cell; grid[i]=EMPTY; break;
          }
        }
      }
    }
  }
  // acid dissolution
  for(let y=0;y<H;y++){
    for(let x=0;x<W;x++){
      if(grid[idx(x,y)]!==ACID) continue;
      const neigh = [[y+1,x],[y-1,x],[y,x-1],[y,x+1]];
      for(const [ny,nx] of neigh){
        if(ny<0||ny>=H||nx<0||nx>=W) continue;
        const n = idx(nx,ny);
        const c = grid[n];
        if(c===SAND || c===WALL) grid[n]=EMPTY;
      }
    }
  }
}

function render(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  for(let y=0;y<H;y++){
    for(let x=0;x<W;x++){
      const c = grid[idx(x,y)];
      if(c===EMPTY) continue;
      ctx.fillStyle = COLORS[c];
      ctx.fillRect(x*CELL, y*CELL, CELL, CELL);
    }
  }
}

function paint(e){
  const rect = canvas.getBoundingClientRect();
  const cx = Math.floor((e.clientX - rect.left) * W / rect.width);
  const cy = Math.floor((e.clientY - rect.top) * H / rect.height);
  for(let dy=-1; dy<=1; dy++){
    for(let dx=-1; dx<=1; dx++){
      const x = cx+dx, y = cy+dy;
      if(x<0||x>=W||y<0||y>=H) continue;
      grid[idx(x,y)] = currentMat;
    }
  }
}

let painting=false;
canvas.addEventListener('mousedown', e=>{painting=true;paint(e);});
canvas.addEventListener('mousemove', e=>{if(painting) paint(e);});
window.addEventListener('mouseup', ()=>painting=false);

document.querySelectorAll('button[id^="mat-"]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    document.querySelectorAll('button[id^="mat-"]').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const name = btn.id.replace('mat-','');
    currentMat = CODE[name] ?? EMPTY;
  });
});
document.getElementById('clear').addEventListener('click', ()=>{
  grid.fill(EMPTY);
  render();
});

function loop(){
  step();
  render();
  requestAnimationFrame(loop);
}
render();
loop();

window.sim = {
  w:W, h:H,
  tick(n){ for(let i=0;i<n;i++) step(); },
  get(x,y){ if(x<0||x>=W||y<0||y>=H) return null; return NAME[grid[idx(x,y)]]; },
  set(x,y,material){ if(x<0||x>=W||y<0||y>=H) return; const c = CODE[material]; if(c!==undefined) grid[idx(x,y)] = c; },
  clear(){ grid.fill(EMPTY); }
};
</script>
</body>
</html>
